/* What the owner's Kernel hands to the child, field by field.
 *
 * Two fields are cleared by the RUNTIME before the child is built — `prompt`,
 * replaced by the entry's own legacy prompt, and `json_schema`, because the
 * parent's structured-output contract is not the child's. Everything else is
 * carried. This is why the editor hands over nothing of its own and projects
 * nothing: `preflight` and `convert_legacy_pools` build the identical child,
 * and the owner's own Kernel is left exactly as the author wrote it. */

export const CAPTURED_CHILD_KERNEL = Object.freeze({
  legacy_prompt: "Child instructions",
  owner: {"schema_version": 1, "profile": {"id": "anthropic-choice", "provider": "anthropic", "model": "claude-x", "protocol": "anthropic", "endpoint": "https://api.openai.com/v1/responses", "credential_ref": "anthropic", "context_window": 128000, "output_limit": 4096, "capabilities": {"json_schema": true, "images": false, "files": false}}, "prompt": "Parent authored prompt", "max_iterations": 11, "output_tokens": 2048, "history": "none", "overflow": "compress", "json_schema": {"type": "object", "properties": {"parent": {"type": "string"}}}},
  child: {"history": "none", "json_schema": null, "max_iterations": 11, "output_tokens": 2048, "overflow": "compress", "profile": {"capabilities": {"files": false, "images": false, "json_schema": true}, "context_window": 128000, "credential_ref": "anthropic", "endpoint": "https://api.openai.com/v1/responses", "id": "anthropic-choice", "model": "claude-x", "output_limit": 4096, "protocol": "anthropic", "provider": "anthropic"}, "prompt": "Child instructions", "schema_version": 1},
  owner_after: {"history": "none", "json_schema": {"properties": {"parent": {"type": "string"}}, "type": "object"}, "max_iterations": 11, "output_tokens": 2048, "overflow": "compress", "profile": {"capabilities": {"files": false, "images": false, "json_schema": true}, "context_window": 128000, "credential_ref": "anthropic", "endpoint": "https://api.openai.com/v1/responses", "id": "anthropic-choice", "model": "claude-x", "output_limit": 4096, "protocol": "anthropic", "provider": "anthropic"}, "prompt": "Parent authored prompt", "schema_version": 1},
  preflight_child_is_the_same: true,
});

/* What a converted entry keeps of what it declared.
 *
 * The panel states that converting keeps the tools, delegation modes, memory
 * and parallel safety each subagent already declared, and that their prompts
 * come with them. This is that statement measured, in both legacy formats,
 * with values that are not the defaults — an empty `allowed_tools` among
 * them, because the default is `null`, which means unrestricted: a lost
 * restriction here would be a widened one.
 *
 * The declared `description` is kept too, verbatim, including the padding it
 * was stored with, and the Agent the conversion builds carries the same text.
 * The panel's two statements do not mention descriptions and are not changed
 * by this; it is recorded because it used to be dropped. */

export const CAPTURED_INLINE_PRESERVED_POLICY = Object.freeze([
  Object.freeze({"prompt_format": "skeleton", "declared": {"description": "  exact child description  ", "allowed_modes": ["worker"], "output_mode": "full_trace", "memory_policy": "scoped_persistent", "parallel_safe": false, "allowed_tools": []}, "stored": {"description": "  exact child description  ", "allowed_modes": ["worker"], "output_mode": "full_trace", "memory_policy": "scoped_persistent", "parallel_safe": false, "allowed_tools": []}, "disabled_tools": ["write"], "child_description": "  exact child description  ", "carried_prompt": "Child instructions"}),
  Object.freeze({"prompt_format": "soul", "declared": {"description": "  exact child description  ", "allowed_modes": ["worker"], "output_mode": "full_trace", "memory_policy": "scoped_persistent", "parallel_safe": false, "allowed_tools": []}, "stored": {"description": "  exact child description  ", "allowed_modes": ["worker"], "output_mode": "full_trace", "memory_policy": "scoped_persistent", "parallel_safe": false, "allowed_tools": []}, "disabled_tools": ["write"], "child_description": "  exact child description  ", "carried_prompt": "Child instructions"}),
]);
